const input = $input.first().json;
const sources = Array.isArray(input.sources) ? input.sources : [];
const allowedSlack = new Set(["C0AUQKNR8CF", "C09AF0NQJE7"]);
const output = [];
for (const source of sources) {
  if (!source || source.enabled === false) continue;
  if (source.kind === "slack_channel" && !allowedSlack.has(source.external_id)) continue;
  if (!["slack_channel", "google_doc", "google_sheet"].includes(source.kind)) continue;
  output.push({
    json: {
      id: String(source.id),
      kind: String(source.kind),
      label: String(source.label || source.external_id),
      external_id: String(source.external_id),
      url: String(source.url || ""),
      last_cursor: source.last_cursor && typeof source.last_cursor === "object" ? source.last_cursor : {},
      run_id: String($execution.id)
    }
  });
}
if (!output.length) throw new Error("Dashboard returned no enabled Ask Sales knowledge sources");
return output;
